      {"fonte_id": "f_bbb437fd83", "localizador": "L06"}
    ],
    "lacunas": [],
    "motivo": "A linha base declarada termina em D10.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_41bd418f24", "localizador": "L01"},
      {"fonte_id": "f_e3f0ade479", "localizador": "L01"},
      {"fonte_id": "f_52a04b86dd", "localizador": "L02"},
      {"fonte_id": "f_d96520b3de", "localizador": "L05"}
    ],
    "lacunas": [
      "Não há decisão de aceite do lote substituto nem duração definida para eventual readequação.",
      "As precedências e requisitos de disponibilidade são remetidos a uma ficha relacional cujo conteúdo não está disponível; não é possível estabelecer o efeito no término."
    ],
    "motivo": "A disponibilidade do substituto e a incerteza de aceite/readequação não determinam, sem as relações de precedência, uma data final ou direção de variação.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"},
      {"fonte_id": "f_41bd418f24", "localizador": "L01"},
      {"fonte_id": "f_e3f0ade479", "localizador": "L01"},
      {"fonte_id": "f_d96520b3de", "localizador": "L05"}
    ],
    "lacunas": [
      "Faltam a decisão de aceite, eventual prazo de readequação e as relações de precedência necessárias para comparar o término novo com D10."
    ],
    "motivo": "O aviso altera a disponibilidade do cartucho, mas os dados visíveis não bastam para afirmar uma variação do término nem sua direção.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"},
      {"fonte_id": "f_8ca6cc3cb4", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "A linha base declara R$ 5.000,00, também conferida pela soma das parcelas únicas.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_41bd418f24", "localizador": "L01"},
      {"fonte_id": "f_e3f0ade479", "localizador": "L01"},
      {"fonte_id": "f_77c5d27cd0", "localizador": "L02"},
      {"fonte_id": "f_e63d1b2e94", "localizador": "L02"}
    ],
    "lacunas": [
      "O custo de eventual readequação não está definido.",
      "A incidência de extensão depende do término final, que não é determinável com os dados disponíveis."
    ],
    "motivo": "A troca tem cobrança conhecida, mas os custos adicionais possíveis impedem determinar o custo total novo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {"fonte_id": "f_41bd418f24", "localizador": "L01"},
      {"fonte_id": "f_bbb437fd83", "localizador": "L06"},
      {"fonte_id": "f_aa2f56bbb7", "localizador": "L03"},
      {"fonte_id": "f_77c5d27cd0", "localizador": "L02"}
    ],
    "lacunas": [
      "A magnitude total é desconhecida: pode haver custo de readequação e a extensão depende do término final."
    ],
    "motivo": "A cobrança adicional de R$ 200,00 não está incluída na linha base; não há crédito por antecipação, e a magnitude total não pode ser apurada.",
    "unidade": "BRL_centavo"
  }
}

